require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';
$id=max(1,(int)($_GET['id']??$_POST['id']??0));$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);$repo=new QualitySystem\Repositories\ProgramManualRepository($conn);$manual=$repo->find($id,$role,$user);if(!$manual){http_response_code(404);exit('Program manual not found.');}$service=new QualitySystem\Services\ProgramManualAutomationService($conn,$repo);if($_SERVER['REQUEST_METHOD']==='POST'){$summary=$service->run($id,$role,$user);}else{$summary=$service->summary($id);}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manual automation</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1000px;margin:auto;padding:1rem}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd3da;padding:.7rem}.alert{padding:.8rem;background:#fff3cd;margin:.5rem 0}</style></head><body><?php require __DIR__.'/nav.php';?><main><p><a href="/program-manuals/<?=$id?>">← Program manual</a></p><h1>Matching, Tasks and Notifications</h1><p>Automatically matches by exact code/email first, then normalized label similarity. Suggestions still require human review.</p><?php if(QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><button>Run automation</button></form><?php endif;?><h2>Mapping summary</h2><table><thead><tr><th>Source</th><th>Status</th><th>Count</th></tr></thead><tbody><?php foreach($summary['mappings']as$r):?><tr><td><?=$h($r['source_type'])?></td><td><?=$h($r['status'])?></td><td><?=(int)$r['count']?></td></tr><?php endforeach;?></tbody></table><h2>Open notifications</h2><?php foreach($summary['notifications']as$n):?><p class="alert"><?=$h($n['message'])?><?=$n['due_date']?' · Due '.$h($n['due_date']):''?></p><?php endforeach;?><?php if(!$summary['notifications']):?><p>No open notifications.</p><?php endif;?></main></body></html>
